        String tag = element.getTagName();
        if (tag == null || tag.isEmpty()) {
            return;
        }

        int colonIndex = tag.indexOf(':');
        if (colonIndex != -1) {
            tag = tag.substring(colonIndex + 1);
        }

        if (tag.indexOf('.') != -1) {
            return;
        }

        if (VALID_TAGS.contains(tag)) {
            return;
        }

        String suggestion = findClosestTag(tag);
        if (suggestion != null) {
            String message = String.format("Suspicious tag name `%1$s`; did you mean `%2$s`?", tag, suggestion);
            context.report(ISSUE, context.getLocation(element), message);
        }
    }

    private static String findClosestTag(String tag) {
        String bestMatch = null;
        int bestDistance = Integer.MAX_VALUE;
        int threshold = Math.max(2, tag.length() / 3);

        for (String valid : VALID_TAGS) {
            int dist = levenshtein(tag, valid);
            if (dist <= threshold && dist < bestDistance) {
                bestDistance = dist;
                bestMatch = valid;
            }
        }
        return bestMatch;
    }

    private static int levenshtein(String s1, String s2) {
        int len1 = s1.length();
        int len2 = s2.length();
        int[] prev = new int[len2 + 1];
        int[] curr = new int[len2 + 1];

        for (int j = 0; j <= len2; j++) {
            prev[j] = j;
        }

        for (int i = 1; i <= len1; i++) {
            curr[0] = i;
            for (int j = 1; j <= len2; j++) {
                int cost = s1.charAt(i - 1) == s2.charAt(j - 1) ? 0 : 1;
                curr[j] = Math.min(Math.min(curr[j - 1] + 1, prev[j] + 1), prev[j - 1] + cost);
            }
            int[] temp = prev;
            prev = curr;
            curr = temp;
        }
        return prev[len2];
    }
}
